def solve_costas(n, fixed):
    # fixed is a dict {col: row}

    # state:
    # x: array of size n
    # used_rows: boolean array of size n
    # used_diffs: array of sets or boolean arrays for each distance d

    x = [-1] * n
    used_rows = [False] * n
    # used_diffs[d] will store the differences x[i+d] - x[i]
    # difference can range from -(n-1) to (n-1), so we can map it to 0..2n-2 by adding n-1
    used_diffs = [[False] * (2 * n - 1) for _ in range(n)]

    for c, r in fixed.items():
        x[c] = r
        used_rows[r] = True

    def solve(c):
        if c == n:
            return True

        if x[c] != -1:
            # Check if valid
            r = x[c]
            valid = True
            for d in range(1, c + 1):
                diff = r - x[c - d]
                if used_diffs[d][diff + n - 1]:
                    valid = False
                    break
            if not valid:
                return False

            # Mark diffs
            for d in range(1, c + 1):
                diff = r - x[c - d]
                used_diffs[d][diff + n - 1] = True

            if solve(c + 1):
                return True

            # Unmark diffs
            for d in range(1, c + 1):
                diff = r - x[c - d]
                used_diffs[d][diff + n - 1] = False

            return False

        for r in range(n):
            if used_rows[r]:
                continue

            valid = True
            for d in range(1, c + 1):
                diff = r - x[c - d]
                if used_diffs[d][diff + n - 1]:
                    valid = False
                    break

            if not valid:
                continue

            x[c] = r
            used_rows[r] = True
            for d in range(1, c + 1):
                diff = r - x[c - d]
                used_diffs[d][diff + n - 1] = True

            if solve(c + 1):
                return True

            x[c] = -1
            used_rows[r] = False
            for d in range(1, c + 1):
                diff = r - x[c - d]
                used_diffs[d][diff + n - 1] = False

        return False

    if solve(0):
        return x
    else:
        return None

