def solve_costas(n):
    def search(c, x):
        if c == n:
            return x
        for r in range(n):
            if r in x:
                continue

            # Check displacements
            valid = True
            for prev_c in range(c):
                prev_r = x[prev_c]
                dr = r - prev_r
                dc = c - prev_c

                # Check if this displacement already exists
                conflict = False
                for i in range(c):
                    for j in range(i + 1, c):
                        if j - i == dc and x[j] - x[i] == dr:
                            conflict = True
                            break
                    if conflict:
                        break
                if conflict:
                    valid = False
                    break

            if valid:
                res = search(c + 1, x + [r])
                if res:
                    return res
        return None

    return search(0, [])

