def solve():
    N = 5
    board_size = N * N

    # Adjacency list for knight moves
    adj = [[] for _ in range(board_size)]
    for r in range(N):
        for c in range(N):
            u = r * N + c
            for dr, dc in [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    v = nr * N + nc
                    adj[u].append(v)

    fixed = {
        0: 0,
        3: 23,
        4: 16,
        5: 5,
        15: 15,
        22: 24
    }

    path = [-1] * board_size
    visited = [False] * board_size

    for k, v in fixed.items():
        if k == 0:
            path[0] = v
            visited[v] = True

    def dfs(step, current):
        if step == board_size:
            return True

        if step in fixed:
            nxt = fixed[step]
            if not visited[nxt] and nxt in adj[current]:
                path[step] = nxt
                visited[nxt] = True
                if dfs(step + 1, nxt):
                    return True
                visited[nxt] = False
                path[step] = -1
            return False

        # Warnsdorff's heuristic: sort by degree of unvisited neighbors
        neighbors = []
        for nxt in adj[current]:
            if not visited[nxt]:
                degree = sum(1 for nn in adj[nxt] if not visited[nn])
                neighbors.append((degree, nxt))

        neighbors.sort()

        for _, nxt in neighbors:
            path[step] = nxt
            visited[nxt] = True
            if dfs(step + 1, nxt):
                return True
            visited[nxt] = False
            path[step] = -1

        return False

    if dfs(1, 0):
        print("SAT")
        print(path)
    else:
        print("UNSAT")

solve()

def solve_langford(n):
    seq = [0] * (2 * n)
    def backtrack(num):
        if num == 0:
            return True
        for i in range(2 * n - num - 1):
            if seq[i] == 0 and seq[i + num + 1] == 0:
                seq[i] = num
                seq[i + num + 1] = num
                if backtrack(num - 1):
                    return True
                seq[i] = 0
                seq[i + num + 1] = 0
        return False
    if backtrack(n):
        return seq
    return None

