def solve_langford_all(n, fixed):
    seq = [0] * (2 * n)
    for idx, val in fixed.items():
        seq[idx] = val

    sols = []
    def solve(idx):
        if idx == 2 * n:
            sols.append(list(seq))
            return
        if seq[idx] != 0:
            solve(idx + 1)
            return

        for v in range(1, n + 1):
            if seq.count(v) == 2:
                continue
            if seq.count(v) == 1:
                first_idx = seq.index(v)
                if idx - first_idx == v + 1:
                    seq[idx] = v
                    solve(idx + 1)
                    seq[idx] = 0
                continue

            if seq.count(v) == 0:
                if idx + v + 1 < 2 * n and seq[idx + v + 1] == 0:
                    seq[idx] = v
                    seq[idx + v + 1] = v
                    solve(idx + 1)
                    seq[idx] = 0
                    seq[idx + v + 1] = 0

    solve(0)
    return sols

