                if model[vpool.id(f"e_{i}_{j}") - 1] > 0:
                    edges.append((i, j))

        # Check if bipartite
        from collections import defaultdict
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        color = {}
        is_bipartite = True
        for i in range(n):
            if i not in color:
                q = [i]
                color[i] = 0
                while q:
                    u = q.pop(0)
                    for v in adj[u]:
                        if v not in color:
                            color[v] = 1 - color[u]
                            q.append(v)
                        elif color[v] == color[u]:
                            is_bipartite = False
                            break
                    if not is_bipartite:
                        break
            if not is_bipartite:
                break

        if not is_bipartite:
            print(edges)
            break
        else:
            # Block this graph
            blocking_clause = []
            for i in range(n):
                for j in range(i+1, n):
                    if (i, j) in edges:
                        blocking_clause.append(-edge_var(i, j))
                    else:
