        for r in range(9):
            for c in range(9):
                if grid[r][c] == 0:
                    for k in range(1, 10):
                        if is_valid(grid, r, c, k):
                            grid[r][c] = k
                            if solve(grid):
                                return True
                            grid[r][c] = 0
                    return False
        return True

    if solve(grid):
        return grid
    else:
        return None

